package dev.aura.player;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import android.content.*;import android.net.Uri;import java.util.*;import java.util.concurrent.*;import java.io.*;import org.json.*;
@RunWith(AndroidJUnit4.class)
public class FolderMemoryTest {
 final android.app.Instrumentation inst=InstrumentationRegistry.getInstrumentation();final Context c=inst.getTargetContext();MainActivity activity;Map<String,String> saved=new HashMap<>();Map<String,byte[]> backups=new HashMap<>();boolean scan;
 @Before public void setup()throws Exception{var prefs=c.getSharedPreferences("aura",0);for(String key:List.of("lastLibraryTab","lastLibrarySource","lastFolderSource","lastFolderCursor.all","lastFolderCursor.local","lastFolderCursor.drive"))saved.put(key,prefs.getString(key,null));scan=prefs.getBoolean("scanOnLaunch",false);prefs.edit().putBoolean("scanOnLaunch",false).commit();for(String name:List.of("library.json","drive-library.json")){File f=new File(c.getFilesDir(),name);backups.put(name,f.isFile()?java.nio.file.Files.readAllBytes(f.toPath()):null);}DriveAuth.get(c).accept("folder-memory","folder@example.invalid","Test","test-token");}
 @After public void cleanup()throws Exception{if(activity!=null)main(()->{activity.finish();return null;});DriveAuth.get(c).clear();for(var e:backups.entrySet()){File f=new File(c.getFilesDir(),e.getKey());if(e.getValue()==null)f.delete();else java.nio.file.Files.write(f.toPath(),e.getValue());}var edit=c.getSharedPreferences("aura",0).edit().putBoolean("scanOnLaunch",scan);saved.forEach((key,value)->{if(value==null)edit.remove(key);else edit.putString(key,value);});edit.commit();}
 Track track(boolean drive)throws Exception{return new Track(drive?DriveUris.file("folder-memory","song","Song.flac").toString():"file:///folder-memory.flac","Song","Artist","Album","Music/Albums/High Detail",1000,"").withPath(List.of(new FolderTree.Part("root","Music"),new FolderTree.Part("albums","Albums"),new FolderTree.Part("detail","High Detail")));}
 @Test public void coldActivityStartAndHomeFolderShortcutRestoreLocalAndDrivePaths()throws Exception{Track local=track(false),cloud=track(true);java.nio.file.Files.write(new File(c.getFilesDir(),"library.json").toPath(),new JSONArray().put(local.json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));java.nio.file.Files.write(new File(c.getFilesDir(),"drive-library.json").toPath(),new JSONObject().put("account","folder-memory").put("tracks",new JSONArray().put(cloud.json())).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));for(Track t:List.of(local,cloud)){String storage=t.drive()?"drive":"local";var tree=new FolderTree(List.of(t));String path=tree.nodes.values().stream().filter(n->n.name.equals("High Detail")).findFirst().orElseThrow().id;launch();main(()->{set("tab","폴더");set("source",storage);set("folderCursor",path);go("library");return null;});await(()->c.getSharedPreferences("aura",0).getString("lastFolderCursor."+storage,"").equals(path),5000);main(()->{activity.finish();return null;});activity=null;launch();assertEquals("폴더",main(()->get("tab")));assertEquals(storage,main(()->get("source")));assertEquals(path,main(()->get("folderCursor")));main(()->{var m=MainActivity.class.getDeclaredMethod("browseLibrary",String.class);m.setAccessible(true);m.invoke(activity,"폴더");return null;});await(()->main(()->path.equals(get("folderCursor"))),5000);main(()->{activity.finish();return null;});activity=null;}}
 @Test public void removedFolderFallsBackToClosestExistingParent()throws Exception{var tree=new FolderTree(List.of(track(false)));var parent=tree.nodes.values().stream().filter(n->n.name.equals("Albums")).findFirst().orElseThrow();assertEquals(parent,tree.closest(parent.id+"/deleted/child"));}
 void launch()throws Exception{activity=(MainActivity)inst.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->main(()->get("player")!=null&&!(Boolean)get("libraryLoading")),10000);}Object get(String key)throws Exception{var f=MainActivity.class.getDeclaredField(key);f.setAccessible(true);return f.get(activity);}void set(String key,Object value)throws Exception{var f=MainActivity.class.getDeclaredField(key);f.setAccessible(true);f.set(activity,value);}void go(String p)throws Exception{var m=MainActivity.class.getDeclaredMethod("go",String.class);m.setAccessible(true);m.invoke(activity,p);} <T>T main(Callable<T> action)throws Exception{FutureTask<T> task=new FutureTask<>(action);inst.runOnMainSync(task);return task.get(15,TimeUnit.SECONDS);}void await(Callable<Boolean> condition,long timeout)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+timeout;while(!condition.call()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(40);assertTrue(condition.call());}
}
